import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[][] m = {{4, 7}, {1, 3}, {8, 10}, {2, 5}, {6, 9}};
        // Both methods start by sorting the meetings by end time.
        Arrays.sort(m, (a, b) -> Integer.compare(a[1], b[1]));
        StringBuilder sb = new StringBuilder("Meetings by end time:");
        for (int[] x : m) sb.append(" (" + x[0] + "," + x[1] + ")");
        System.out.println(sb);

        // Greedy: one pass, one choice per meeting, never undone.
        // Time O(N log N) for the sort, O(1) extra space.
        int count = 0, lastEnd = Integer.MIN_VALUE;
        for (int[] x : m) {
            if (x[0] >= lastEnd) { count++; lastEnd = x[1]; }
        }

        // DP: dp[i] = most meetings in a schedule whose last meeting is i.
        // It tries every earlier meeting j. Time O(N^2), space O(N).
        int n = m.length, best = 0;
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) {
            dp[i] = 1;
            for (int j = 0; j < i; j++) {
                if (m[j][1] <= m[i][0]) dp[i] = Math.max(dp[i], dp[j] + 1);
            }
            best = Math.max(best, dp[i]);
        }
        System.out.println("Greedy answer: " + count);
        System.out.println("DP answer: " + best);
    }
}

