    // Both methods start by sorting the meetings by end time.
    sort(m.begin(), m.end(), [](const pair<int, int>& a, const pair<int, int>& b) { return a.second < b.second; });
    cout << "Meetings by end time:";
    for (auto& x : m) cout << " (" << x.first << "," << x.second << ")";
    cout << "\n";

    // Greedy: one pass, one choice per meeting, never undone.
    // Time O(N log N) for the sort, O(1) extra space.
    int count = 0, lastEnd = INT_MIN;
    for (auto& x : m) {
        if (x.first >= lastEnd) { count++; lastEnd = x.second; }
    }

    // DP: dp[i] = most meetings in a schedule whose last meeting is i.
    // It tries every earlier meeting j. Time O(N^2), space O(N).
    int n = m.size(), best = 0;
    vector<int> dp(n, 1);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (m[j].second <= m[i].first) dp[i] = max(dp[i], dp[j] + 1);
        }
        best = max(best, dp[i]);
    }
    cout << "Greedy answer: " << count << "\n";
    cout << "DP answer: " << best << "\n";
    return 0;
}

