import java.util.*;

public class Main {
    // Greedy: meetings are sorted by end time; keep each one that fits.
    static int greedy(int[][] m) {
        int count = 0, lastEnd = Integer.MIN_VALUE;
        for (int[] x : m) if (x[0] >= lastEnd) { count++; lastEnd = x[1]; }
        return count;
    }

    // Brute force: try every subset (bitmask) and keep the largest valid one.
    static int brute(int[][] m) {
        int n = m.length, best = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            int count = 0, lastEnd = Integer.MIN_VALUE;
            boolean ok = true;
            for (int i = 0; i < n && ok; i++) {
                if ((mask >> i & 1) == 0) continue;
                if (m[i][0] >= lastEnd) { count++; lastEnd = m[i][1]; } else ok = false;
            }
            if (ok) best = Math.max(best, count);
        }
        return best;
    }

    public static void main(String[] args) {
        int[][][] tests = {
            {{0, 10}, {1, 2}, {3, 4}},
            {{1, 5}, {4, 7}, {6, 10}},
            {{1, 4}, {3, 5}, {0, 6}, {5, 7}, {3, 9}, {5, 9}, {6, 10}, {8, 11}}
        };
        // Greedy is O(N log N); brute force is O(2^N * N), fine for N <= 20.
        for (int t = 0; t < tests.length; t++) {
            int[][] m = tests[t];
            Arrays.sort(m, (a, b) -> Integer.compare(a[1], b[1]));
            int g = greedy(m), b = brute(m);
            System.out.println("Test " + (t + 1) + ": " + m.length + " meetings, greedy = " + g
                + ", brute force = " + b + (g == b ? " -> match" : " -> MISMATCH"));
        }
    }
}

