    n, best = len(m), 0
    for mask in range(1 << n):
        count, last_end, ok = 0, float("-inf"), True
        for i in range(n):
            if not (mask >> i) & 1:
                continue
            if m[i][0] >= last_end:
                count, last_end = count + 1, m[i][1]
            else:
                ok = False
                break
        if ok:
            best = max(best, count)
    return best


