#include <bits/stdc++.h>
using namespace std;
typedef vector<pair<int, int>> Meetings;

// Greedy: meetings are sorted by end time; keep each one that fits.
int greedy(const Meetings& m) {
    int count = 0, lastEnd = INT_MIN;
    for (auto& x : m) if (x.first >= lastEnd) { count++; lastEnd = x.second; }
    return count;
}

// Brute force: try every subset (bitmask) and keep the largest valid one.
int brute(const Meetings& m) {
    int n = m.size(), best = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        int count = 0, lastEnd = INT_MIN;
        bool ok = true;
        for (int i = 0; i < n && ok; i++) {
            if (((mask >> i) & 1) == 0) continue;
            if (m[i].first >= lastEnd) { count++; lastEnd = m[i].second; } else ok = false;
        }
        if (ok) best = max(best, count);
    }
    return best;
}

int main() {
    vector<Meetings> tests = {
        {{0, 10}, {1, 2}, {3, 4}},
        {{1, 5}, {4, 7}, {6, 10}},
        {{1, 4}, {3, 5}, {0, 6}, {5, 7}, {3, 9}, {5, 9}, {6, 10}, {8, 11}}
    };
    // Greedy is O(N log N); brute force is O(2^N * N), fine for N <= 20.
    for (size_t t = 0; t < tests.size(); t++) {
        Meetings& m = tests[t];
        sort(m.begin(), m.end(), [](const pair<int, int>& a, const pair<int, int>& b) { return a.second < b.second; });
        int g = greedy(m), b = brute(m);
        cout << "Test " << t + 1 << ": " << m.size() << " meetings, greedy = " << g
             << ", brute force = " << b << (g == b ? " -> match" : " -> MISMATCH") << "\n";
    }
    return 0;
}

