#include <bits/stdc++.h>
using namespace std;
typedef vector<pair<int, int>> Meetings;

// rule 0 = earliest start, 1 = shortest first, 2 = earliest end
int key(const pair<int, int>& x, int rule) {
    return rule == 0 ? x.first : rule == 1 ? x.second - x.first : x.second;
}

// Sort by the rule, then keep every meeting that does not clash with
// the ones already kept. Time O(N^2) here (N is tiny), space O(N).
int pick(Meetings a, int rule) {
    stable_sort(a.begin(), a.end(), [rule](const pair<int, int>& x, const pair<int, int>& y) {
        return key(x, rule) < key(y, rule);
    });
    Meetings kept;
    for (auto& x : a) {
        bool clash = false;
        // Two meetings clash when each starts before the other ends.
        for (auto& k : kept) if (x.first < k.second && k.first < x.second) clash = true;
        if (!clash) kept.push_back(x);
    }
    return kept.size();
}

int main() {
    vector<Meetings> tests = {{{0, 10}, {1, 2}, {3, 4}}, {{1, 5}, {4, 7}, {6, 10}}};
