using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

class Program {
    // rule 0 = earliest start, 1 = shortest first, 2 = earliest end
    static int Key(int[] x, int rule) {
        return rule == 0 ? x[0] : rule == 1 ? x[1] - x[0] : x[1];
    }

    // Sort by the rule, then keep every meeting that does not clash with
    // the ones already kept. Time O(N^2) here (N is tiny), space O(N).
    static int Pick(int[][] m, int rule) {
        List<int[]> kept = new List<int[]>();
        foreach (int[] x in m.OrderBy(v => Key(v, rule))) {
            bool clash = false;
            // Two meetings clash when each starts before the other ends.
            foreach (int[] k in kept) if (x[0] < k[1] && k[0] < x[1]) clash = true;
            if (!clash) kept.Add(x);
        }
        return kept.Count;
    }

    static void Main() {
        int[][][] tests = {
            new[] { new[] {0, 10}, new[] {1, 2}, new[] {3, 4} },
            new[] { new[] {1, 5}, new[] {4, 7}, new[] {6, 10} }
        };
        string[] names = { "earliest start", "shortest first", "earliest end" };
        foreach (int[][] m in tests) {
            StringBuilder sb = new StringBuilder("Meetings:");
            foreach (int[] x in m) sb.Append(" (" + x[0] + "," + x[1] + ")");
            Console.WriteLine(sb.ToString());
            // Only "earliest end" reaches the best answer (2) on both inputs.
            for (int r = 0; r < 3; r++) Console.WriteLine("  " + names[r] + ": " + Pick(m, r));
        }
    }
}

