import java.util.*;

public class Main {
    public static void main(String[] args) {
        String[] id = {"a", "b", "c", "d", "e"};
        int[] deadline = {2, 1, 2, 1, 3};
        int[] profit = {100, 19, 27, 25, 15};
        int n = id.length, maxD = 3;
        StringBuilder sb = new StringBuilder("Jobs (deadline, profit):");
        for (int i = 0; i < n; i++) sb.append(" " + id[i] + "(" + deadline[i] + "," + profit[i] + ")");
        System.out.println(sb);

        // Look at the jobs from the highest profit to the lowest.
        Integer[] order = {0, 1, 2, 3, 4};
        Arrays.sort(order, (x, y) -> Integer.compare(profit[y], profit[x]));

        String[] slot = new String[maxD + 1];   // slot[t] = job done in hour t
        int total = 0;
        for (int j : order) {
            // Walk back from the deadline to find the latest free hour.
            int t = deadline[j];
            while (t >= 1 && slot[t] != null) t--;
            if (t >= 1) {
                slot[t] = id[j];
                total += profit[j];
                System.out.println("Take " + id[j] + " -> slot " + t);
            } else {
                System.out.println("Skip " + id[j]);
            }
        }
        // Time O(N log N + N * D), space O(D). Union-find makes it O(N log N).
        sb = new StringBuilder("Schedule:");
        for (int t = 1; t <= maxD; t++) sb.append(" " + (slot[t] == null ? "-" : slot[t]));
        System.out.println(sb);
        System.out.println("Total profit: " + total);
    }
}

