    vector<string> slot(maxD + 1, "");   // slot[t] = job done in hour t
    int total = 0;
    for (int j : order) {
        // Walk back from the deadline to find the latest free hour.
        int t = deadline[j];
        while (t >= 1 && !slot[t].empty()) t--;
        if (t >= 1) {
            slot[t] = id[j];
            total += profit[j];
            cout << "Take " << id[j] << " -> slot " << t << "\n";
        } else {
            cout << "Skip " << id[j] << "\n";
        }
    }
    // Time O(N log N + N * D), space O(D). Union-find makes it O(N log N).
    cout << "Schedule:";
    for (int t = 1; t <= maxD; t++) cout << " " << (slot[t].empty() ? "-" : slot[t]);
    cout << "\nTotal profit: " << total << "\n";
    return 0;
}

