import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] value = {100, 120, 60}, weight = {20, 30, 10};
        int cap = 50, n = value.length;
        StringBuilder sb = new StringBuilder("Capacity " + cap + ", items (value, weight):");
        for (int i = 0; i < n; i++) sb.append(" (" + value[i] + "," + weight[i] + ")");
        System.out.println(sb);

        // Sort by value per kg, best first. Cross-multiply to avoid doubles.
        Integer[] order = {0, 1, 2};
        Arrays.sort(order, (a, b) -> Long.compare((long) value[b] * weight[a], (long) value[a] * weight[b]));

        // Fractional: take whole items, then a slice of the first that does not fit.
        double frac = 0; int left = cap;
        for (int i : order) {
            int take = Math.min(left, weight[i]);
            frac += (double) value[i] * take / weight[i];
            left -= take;
        }
        // 0/1 with the same rule: an item is taken whole or not at all.
        int greedy01 = 0; left = cap;
        for (int i : order) if (weight[i] <= left) { greedy01 += value[i]; left -= weight[i]; }

        // 0/1 done properly with DP: dp[w] = best value with capacity w.
        int[] dp = new int[cap + 1];
        for (int i = 0; i < n; i++)
            for (int w = cap; w >= weight[i]; w--)
                dp[w] = Math.max(dp[w], dp[w - weight[i]] + value[i]);

        // Greedy: O(N log N) time, O(N) space. DP: O(N * W) time, O(W) space.
        System.out.println("Fractional greedy: " + String.format("%.2f", frac));
        System.out.println("0/1 ratio greedy: " + greedy01);
        System.out.println("0/1 DP (optimal): " + dp[cap]);
    }
}

