import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] freq = {45, 13, 9, 5, 16, 12};
        Arrays.sort(freq);
        StringBuilder sb = new StringBuilder("Frequencies (sorted):");
        for (int f : freq) sb.append(" " + f);
        System.out.println(sb);

        // Two queues instead of a heap: sorted leaves, and merged nodes.
        // Merged sums come out in rising order, so both queues stay sorted
        // and the two smallest nodes are always at the two fronts.
        int n = freq.length, i = 0, j = 0, total = 0;
        int[] merged = new int[n];
        int mCount = 0;
        for (int step = 0; step < n - 1; step++) {
            int[] pair = new int[2];
            for (int k = 0; k < 2; k++) {
                // Take the smaller front of the two queues.
                if (i < n && (j >= mCount || freq[i] <= merged[j])) pair[k] = freq[i++];
                else pair[k] = merged[j++];
            }
            int sum = pair[0] + pair[1];
            merged[mCount++] = sum;
            total += sum;   // every merge adds one bit to all symbols below it
            System.out.println("Merge " + pair[0] + " + " + pair[1] + " = " + sum);
        }
        // Time O(N log N) for the sort, then O(N); space O(N).
        System.out.println("Total bits: " + total);
    }
}

