import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[][] m = {{900, 910}, {940, 1200}, {950, 1120}, {1100, 1130}, {1500, 1900}, {1800, 2000}};
        StringBuilder sb = new StringBuilder("Meetings:");
        for (int[] x : m) sb.append(" (" + x[0] + "," + x[1] + ")");
        System.out.println(sb);

        // Sort the start times and the end times separately.
        int n = m.length;
        int[] start = new int[n], end = new int[n];
        for (int i = 0; i < n; i++) { start[i] = m[i][0]; end[i] = m[i][1]; }
        Arrays.sort(start);
        Arrays.sort(end);

        int rooms = 0, best = 0, i = 0, j = 0;
        while (i < n) {
            if (start[i] < end[j]) {
                // A meeting starts before the earliest one ends: one more room.
                rooms++; i++;
                best = Math.max(best, rooms);
            } else {
                // A meeting has ended (touching counts as free): release a room.
                rooms--; j++;
            }
        }
        // Time O(N log N) for the sorts, space O(N).
        System.out.println("Rooms needed: " + best);
    }
}

