public class Main {
    public static void main(String[] args) {
        int[] gas = {1, 2, 3, 4, 5}, cost = {3, 4, 5, 1, 2};
        StringBuilder a = new StringBuilder("gas: "), b = new StringBuilder("cost:");
        for (int g : gas) a.append(" " + g);
        for (int c : cost) b.append(" " + c);
        System.out.println(a);
        System.out.println(b);

        int total = 0, tank = 0, start = 0;
        for (int i = 0; i < gas.length; i++) {
            int gain = gas[i] - cost[i];   // fuel won or lost on this leg
            total += gain;
            tank += gain;
            if (tank < 0) {
                // No station from start to i can be the answer: skip them all.
                System.out.println("Tank below zero after station " + i + ", restart at " + (i + 1));
                start = i + 1;
                tank = 0;
            }
        }
        // If the whole circle loses fuel, no start can work.
        int answer = total < 0 ? -1 : start;
        // Time O(N), space O(1).
        System.out.println("Total gain: " + total);
        System.out.println("Start station: " + answer);
    }
}

