code.java:
public class Main {
    // Wrong greedy: always land as far as the current jump allows.
    static int farthestJump(int[] nums) {
        int i = 0, jumps = 0, n = nums.length;
        while (i < n - 1) { i = Math.min(n - 1, i + nums[i]); jumps++; }
        return jumps;
    }

    // Right greedy: curEnd = last index reachable with the jumps used so far,
    // farthest = last index reachable with one more jump.
    static int levels(int[] nums) {
        int jumps = 0, curEnd = 0, farthest = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);
            if (i == curEnd) {      // this level is finished: one more jump
                jumps++;
                curEnd = farthest;
            }
        }
        return jumps;
    }

    public static void main(String[] args) {
        int[] nums = {2, 3, 1, 1, 4};
        StringBuilder sb = new StringBuilder("nums:");
        for (int x : nums) sb.append(" " + x);
        System.out.println(sb);
        // Both run in O(N) time and O(1) space; only the second is optimal.
        System.out.println("Farthest-jump greedy: " + farthestJump(nums) + " jumps");
        System.out.println("Level-by-level greedy: " + levels(nums) + " jumps");
    }
}

