  const n = nums.length;
  while (i < n - 1) { i = Math.min(n - 1, i + nums[i]); jumps++; }
  return jumps;
}

// Right greedy: curEnd = last index reachable with the jumps used so far,
// farthest = last index reachable with one more jump.
function levels(nums) {
  let jumps = 0, curEnd = 0, farthest = 0;
  for (let i = 0; i < nums.length - 1; i++) {
    farthest = Math.max(farthest, i + nums[i]);
    if (i === curEnd) {      // this level is finished: one more jump
      jumps++;
      curEnd = farthest;
    }
  }
  return jumps;
}

