import java.util.*;

public class Main {
    // Greedy: keep taking the largest coin that still fits. -1 if stuck.
    static int greedy(int[] coins, int amount) {
        int count = 0;
        for (int i = coins.length - 1; i >= 0; i--) {
            count += amount / coins[i];
            amount %= coins[i];
        }
        return amount == 0 ? count : -1;
    }

    // DP: dp[x] = fewest coins that make x, built from smaller amounts.
    static int dp(int[] coins, int amount) {
        int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int x = 1; x <= amount; x++)
            for (int c : coins)
                if (c <= x) dp[x] = Math.min(dp[x], dp[x - c] + 1);
        return dp[amount] >= INF ? -1 : dp[amount];
    }

    static void show(int[] coins, int amount) {
        StringBuilder sb = new StringBuilder("Coins:");
        for (int c : coins) sb.append(" " + c);
        System.out.println(sb + ", amount: " + amount);
        System.out.println("  Greedy (largest first): " + greedy(coins, amount));
        System.out.println("  DP (optimal): " + dp(coins, amount));
    }

    public static void main(String[] args) {
        // Greedy is O(coins) time; DP is O(amount * coins) time, O(amount) space.
        show(new int[] {1, 3, 4}, 6);   // greedy uses one coin too many
        show(new int[] {3, 4}, 6);      // greedy wrongly says impossible (-1)
    }
}

