import java.util.*;

public class Main {
    static int[] parent;

    // Union-find "find": the representative of x's connected group.
    static int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }

    public static void main(String[] args) {
        // Edges {u, v, weight} on 4 nodes. Independent set = edges with no cycle.
        int[][] edges = {{1, 2, 5}, {0, 1, 7}, {1, 3, 3}, {0, 2, 6}, {2, 3, 4}};
        parent = new int[] {0, 1, 2, 3};

        // The matroid greedy: heaviest first ...
        Arrays.sort(edges, (a, b) -> Integer.compare(b[2], a[2]));
        int total = 0;
        for (int[] e : edges) {
            int a = find(e[0]), b = find(e[1]);
            String label = "Edge " + e[0] + "-" + e[1] + " weight " + e[2] + ": ";
            // ... and add the edge only if the set stays independent.
            if (a != b) {
                parent[a] = b;
                total += e[2];
                System.out.println(label + "add");
            } else {
                System.out.println(label + "skip (cycle)");
            }
        }
        // Time O(E log E), space O(V).
        System.out.println("Maximum-weight spanning tree: " + total);
    }
}

