import java.util.*;

public class Main {
    public static void main(String[] args) {
        int a = 2000000000, b = -2000000000;
        System.out.println("a = " + a + ", b = " + b);
        // Bug: a - b does not fit in 32 bits, so it wraps to a negative number
        // and the comparator claims a < b.
        int diff = a - b;
        System.out.println("a - b in 32 bits = " + diff + " (negative: wrongly says a < b)");
        // Fix: compare without subtracting.
        System.out.println("Safe compare = " + Integer.compare(a, b) + " (correct: a > b)");

        // Largest Number: put x before y when the text x+y is bigger than y+x.
        String[] nums = {"3", "30", "34", "5", "9"};
        System.out.println("Numbers: " + String.join(" ", nums));
        // Both strings have the same length, so text order equals number order.
        Arrays.sort(nums, (x, y) -> (y + x).compareTo(x + y));
        // Time O(N log N) comparisons of short strings, space O(N).
        System.out.println("Largest number: " + String.join("", nums));
    }
}

