#include <bits/stdc++.h>
using namespace std;

int main() {
    int a = 2000000000, b = -2000000000;
    cout << "a = " << a << ", b = " << b << "\n";
    // Bug: a - b does not fit in 32 bits, so it wraps to a negative number
    // and the comparator claims a < b. (Signed overflow is undefined in C++,
    // so we do the wrap-around with unsigned maths to show it safely.)
    int diff = (int) ((unsigned) a - (unsigned) b);
    cout << "a - b in 32 bits = " << diff << " (negative: wrongly says a < b)\n";
    // Fix: compare without subtracting.
    int safe = a < b ? -1 : a > b ? 1 : 0;
    cout << "Safe compare = " << safe << " (correct: a > b)\n";

    // Largest Number: put x before y when the text x+y is bigger than y+x.
    vector<string> nums = {"3", "30", "34", "5", "9"};
    cout << "Numbers:";
    for (auto& s : nums) cout << " " << s;
    cout << "\n";
    // Both strings have the same length, so text order equals number order.
    sort(nums.begin(), nums.end(), [](const string& x, const string& y) { return x + y > y + x; });
    // Time O(N log N) comparisons of short strings, space O(N).
    cout << "Largest number: ";
    for (auto& s : nums) cout << s;
    cout << "\n";
    return 0;
}

