import java.util.*;

public class Main {
    static final int[] COINS = {1, 3, 4};

    // The solution under test: largest coin first.
    static int greedy(int amount) {
        int count = 0;
        for (int i = COINS.length - 1; i >= 0; i--) { count += amount / COINS[i]; amount %= COINS[i]; }
        return count;
    }

    // The slow but obviously correct reference: try every coin for every amount.
    static int reference(int amount) {
        int[] best = new int[amount + 1];
        for (int x = 1; x <= amount; x++) {
            best[x] = Integer.MAX_VALUE;
            for (int c : COINS) if (c <= x) best[x] = Math.min(best[x], best[x - c] + 1);
        }
        return best[amount];
    }

    public static void main(String[] args) {
        System.out.println("Coins: 1 3 4, random amounts from 1 to 20");
        int seed = 2;   // fixed seed, so a failure can be replayed
        for (int trial = 1; trial <= 100; trial++) {
            seed = (seed * 75 + 74) % 65537;   // tiny random-number generator
            int amount = seed % 20 + 1;        // small inputs give readable failures
            int g = greedy(amount), r = reference(amount);
            if (g != r) {
                System.out.println("Trial " + trial + ": amount " + amount + ", greedy " + g + ", reference " + r + " -> MISMATCH");
                return;
            }
            System.out.println("Trial " + trial + ": amount " + amount + ", both " + g + " -> ok");
        }
        // Each trial costs O(amount * coins) time for the reference, O(amount) space.
        System.out.println("All 100 trials passed");
    }
}

