import java.util.*;

public class Main {
    // LRU: evict the page that was used longest ago. Needs only the past.
    static int lru(int[] pages, int cap) {
        List<Integer> frames = new ArrayList<>();   // least recent first
        int faults = 0;
        for (int p : pages) {
            if (frames.remove(Integer.valueOf(p))) { frames.add(p); continue; }   // hit: now most recent
            faults++;
            if (frames.size() == cap) frames.remove(0);
            frames.add(p);
        }
        return faults;
    }

    // Belady: evict the page whose next use is furthest away. Needs the future.
    static int belady(int[] pages, int cap) {
        List<Integer> frames = new ArrayList<>();
        int faults = 0, n = pages.length;
        for (int i = 0; i < n; i++) {
            if (frames.contains(pages[i])) continue;
            faults++;
            if (frames.size() == cap) {
                int victim = 0, far = -1;
                for (int k = 0; k < cap; k++) {
                    int next = i + 1;   // position of the next use of frame k
                    while (next < n && pages[next] != frames.get(k)) next++;
                    if (next > far) { far = next; victim = k; }
                }
                frames.remove(victim);
            }
            frames.add(pages[i]);
        }
        return faults;
    }

    public static void main(String[] args) {
        int[] pages = {7, 0, 1, 2, 0, 3, 0, 4, 2, 3, 0, 3, 2, 1, 2, 0, 1, 7, 0, 1};
        StringBuilder sb = new StringBuilder("Pages:");
        for (int p : pages) sb.append(" " + p);
        System.out.println(sb);
        System.out.println("Cache size: 3");
        // LRU is O(N * C) here; this simple Belady is O(N^2 * C). Space O(C).
        System.out.println("LRU misses: " + lru(pages, 3));
        System.out.println("Belady (optimal) misses: " + belady(pages, 3));
    }
}

