function lru(pages, cap) {
  const frames = [];   // least recent first
  let faults = 0;
  for (const p of pages) {
    const at = frames.indexOf(p);
    if (at >= 0) { frames.splice(at, 1); frames.push(p); continue; }   // hit: now most recent
    faults++;
    if (frames.length === cap) frames.shift();
    frames.push(p);
  }
  return faults;
}

