#include <bits/stdc++.h>
using namespace std;

// LRU: evict the page that was used longest ago. Needs only the past.
int lru(const vector<int>& pages, int cap) {
    vector<int> frames;   // least recent first
    int faults = 0;
    for (int p : pages) {
        auto it = find(frames.begin(), frames.end(), p);
        if (it != frames.end()) { frames.erase(it); frames.push_back(p); continue; }   // hit: now most recent
        faults++;
        if ((int) frames.size() == cap) frames.erase(frames.begin());
        frames.push_back(p);
    }
    return faults;
}

// Belady: evict the page whose next use is furthest away. Needs the future.
int belady(const vector<int>& pages, int cap) {
    vector<int> frames;
    int faults = 0, n = pages.size();
    for (int i = 0; i < n; i++) {
        if (find(frames.begin(), frames.end(), pages[i]) != frames.end()) continue;
        faults++;
        if ((int) frames.size() == cap) {
            int victim = 0, far = -1;
            for (int k = 0; k < cap; k++) {
                int next = i + 1;   // position of the next use of frame k
                while (next < n && pages[next] != frames[k]) next++;
                if (next > far) { far = next; victim = k; }
            }
            frames.erase(frames.begin() + victim);
        }
        frames.push_back(pages[i]);
    }
    return faults;
}

int main() {
    vector<int> pages = {7, 0, 1, 2, 0, 3, 0, 4, 2, 3, 0, 3, 2, 1, 2, 0, 1, 7, 0, 1};
    cout << "Pages:";
    for (int p : pages) cout << " " << p;
    cout << "\nCache size: 3\n";
    // LRU is O(N * C) here; this simple Belady is O(N^2 * C). Space O(C).
    cout << "LRU misses: " << lru(pages, 3) << "\n";
    cout << "Belady (optimal) misses: " << belady(pages, 3) << "\n";
    return 0;
}

